const input = $input.first().json;
console.log('Input recibido:', JSON.stringify(input, null, 2));

let { whatsapp, person_identifier, horario_id } = input;

if (!whatsapp) {
  throw new Error('Falta parámetro: whatsapp. Input: ' + JSON.stringify(input));
}
if (!horario_id) {
  throw new Error('Falta parámetro: horario_id');
}

const wp = String(whatsapp).replace(/'/g, "''");
const pi = person_identifier ? String(person_identifier).replace(/'/g, "''") : null;
const hid = parseInt(horario_id);

let whereClause;
if (pi) {
  whereClause = `l.whatsapp = '${wp}' AND l.person_identifier = '${pi}'`;
} else {
  whereClause = `l.whatsapp = '${wp}'`;
}

const query = `SELECT
  (SELECT to_jsonb(l) FROM leads l WHERE ${whereClause} ORDER BY l.created_at DESC LIMIT 1) AS lead,
  (SELECT to_jsonb(h) FROM horarios h WHERE h.id = ${hid}) AS horario;`;

return [{ json: { query } }];

const result = $input.first().json || {};
const lead = result.lead;
const horario = result.horario;

if (!lead || !lead.id) {
  console.log('DEBUG - Lead no encontrado. Resultado:', JSON.stringify(result));

  // Obtener parámetros originales
  const triggerData = $('When Executed by Another Workflow').first().json;
  throw new Error(`Lead no encontrado para whatsapp='${triggerData.whatsapp}' y person_identifier='${triggerData.person_identifier}'. Verifica que el lead existe en la tabla leads.`);
}

if (!horario || !horario.id) {
  throw new Error('No existe horario con ese id');
}

const whatsapp = lead.whatsapp;
const cupoMax = (horario.cupo_maximo ?? horario.cupo_max);
const cupoActual = horario.cupo_actual ?? 0;

if (cupoMax !== null && cupoMax !== undefined && cupoActual >= cupoMax) {
  throw new Error('Horario sin cupo disponible');
}

const esc = (v) => v === null || v === undefined ? null : String(v).replace(/'/g, "''");
const asSql = (v) => v === null ? 'null' : `'${v}'`;

const nombre = esc(lead.nombre);
const apellido = esc(lead.apellido);
const wp = esc(whatsapp);
const email = esc(lead.email);
const lead_tipo = esc(lead.lead_tipo);
const categoria = esc(lead.categoria);
const origen = esc(lead.origen);
const nivel = esc(lead.nivel);
const objetivo = esc(lead.objetivo);
const resumen = esc(lead.resumen);
const disponibilidad = esc(lead.disponibilidad);
const tags = esc(lead.tags);
const notas = esc(lead.notas);

const query = `INSERT INTO alumnos (nombre, apellido, whatsapp, email, lead_tipo, categoria, origen, nivel, objetivo, resumen, disponibilidad, tags, notas, estado, estado_motivo, estado_fecha, primer_contacto, ultimo_contacto, created_at, updated_at, activo)
VALUES (${asSql(nombre)}, ${asSql(apellido)}, ${asSql(wp)}, ${asSql(email)}, ${asSql(lead_tipo)}, ${asSql(categoria)}, ${asSql(origen)}, ${asSql(nivel)}, ${asSql(objetivo)}, ${asSql(resumen)}, ${asSql(disponibilidad)}, ${asSql(tags)}, ${asSql(notas)}, 'REGISTRADO', 'Eligió horario y quedó registrado', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, true)
RETURNING id, nombre, whatsapp, estado;`;

return [{ json: { query, lead_id: lead.id, horario_id: horario.id } }];

const result = $input.first().json;

if (!result || !result.id) {
  return [{ json: { success: false, message: 'Error al crear alumno' } }];
}

return [{
  json: {
    success: true,
    message: 'Lead convertido a alumno REGISTRADO exitosamente',
    alumno_id: result.id,
    nombre: result.nombre,
    whatsapp: result.whatsapp,
    estado: result.estado
  }
}];

const alumnoData = $input.first().json;

if (!alumnoData || !alumnoData.id) {
  throw new Error('No hay datos de alumno');
}

const alumnoId = alumnoData.id;
const whatsapp = alumnoData.whatsapp;

const query = `UPDATE leads 
SET alumno_id = ${alumnoId}, 
    fecha_conversion = CURRENT_TIMESTAMP
WHERE whatsapp = '${String(whatsapp).replace(/'/g, "''")}'
RETURNING id, nombre, whatsapp, alumno_id, estado;`;

return [{ json: { query } }];
